<?php
require_once __DIR__.'/_lib.php';require_once APP_ROOT.'/lib/simple_pdf.php';
exigirSuperadmin();$p=periodoActivo();if(!$p)die('No existe periodo activo.');$e=eleccionPeriodo((int)$p['id']);if(!$e)die('No existe proceso electoral.');$eid=(int)$e['id'];$seccion=(string)($_GET['seccion']??'todas');if(!in_array($seccion,['todas','matutina','vespertina'],true))$seccion='todas';
$sql="SELECT c.nombre,c.propuesta,c.seccion,COUNT(v.id) votos FROM eleccion_candidatos c LEFT JOIN eleccion_votos v ON v.candidato_id=c.id WHERE c.eleccion_id=? AND c.activo=1";if($seccion!=='todas'){$sql.=' AND c.seccion=? GROUP BY c.id ORDER BY votos DESC,c.nombre';$st=$conexion->prepare($sql);$st->bind_param('is',$eid,$seccion);}else{$sql.=' GROUP BY c.id ORDER BY c.seccion,votos DESC,c.nombre';$st=$conexion->prepare($sql);$st->bind_param('i',$eid);}$st->execute();$rows=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();
registrarAuditoria('EXPORT','Votaciones','eleccion',$eid,'Resultados electorales exportados en PDF. Filtro: '.$seccion.'.',null,null,['seccion'=>$seccion]);
$pdf=new SimplePdf();$pdf->addPage();$pdf->text(48,795,'UNEDID - RESULTADOS ELECTORALES',16,true);$pdf->text(48,774,$e['titulo'],12,true);$pdf->text(48,758,'Periodo: '.$p['nombre'].' | Estado: '.strtoupper($e['estado']),9);$pdf->line(48,748,547,748,1);
$y=722;foreach(['matutina','vespertina'] as $s){if($seccion!=='todas'&&$seccion!==$s)continue;$pob=poblacionEleccion($eid,$s);$v=votosEleccion($eid,$s);$pdf->text(48,$y,strtoupper($s).' - Poblacion: '.$pob.' | Votos: '.$v.' | Participacion: '.($pob?number_format($v/$pob*100,1):'0.0').'%',10,true);$y-=22;foreach($rows as $r){if($r['seccion']!==$s)continue;if($y<90){$pdf->addPage();$y=790;}$pdf->text(60,$y,$r['nombre'],9,true);$pdf->text(430,$y,(string)$r['votos'].' votos',9,true);$y-=15;if(trim((string)$r['propuesta'])!==''){$txt=trim((string)$r['propuesta']);if(function_exists('mb_strimwidth'))$txt=mb_strimwidth($txt,0,78,'...');else$txt=substr($txt,0,78);$pdf->text(70,$y,$txt,8);$y-=18;}$pdf->line(60,$y+8,535,$y+8,.25);}$y-=18;}
$pdf->text(48,55,'Documento generado por el Sistema de Gestion Academica UNEDID.',8);$pdf->output('resultados_elecciones_'.$p['nombre'].'_'.$seccion.'.pdf');
